    for c in range(input_test.shape[1]):
        if input_test[r,c] == 2:
            seed_positions.add((r,c))

print(f"\nSeed positions (value 2): {len(seed_positions)}")
print(sorted(list(seed_positions)))

# Find all 0-regions (4-connected clusters)
def find_zero_regions(grid):
    visited = set()
    regions = []

    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if grid[r,c] == 0 and (r,c) not in visited:
                region = set()
                queue = deque([(r,c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr,cc) in visited:
                        continue
                    visited.add((cr,cc))
                    region.add((cr,cc))
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                            if grid[nr,nc] == 0 and (nr,nc) not in visited:
                                queue.append((nr,nc))
                regions.append(region)
    return regions

# Find all 0-regions
zero_regions = find_zero_regions(input_test)
print(f"\nTotal 0-regions: {len(zero_regions)}")

# Find which 0-regions are 8-adjacent to seeds
eight_adj_to_seed = []
for i, reg in enumerate(zero_regions):
