# Mark all 0s in adjacent regions to become 2
for i, reg, size in eight_adj_to_seed:
    for r,c in reg:
        output_test[r,c] = 2

print("\nOutput grid:")
for i, row in enumerate(output_test):
    print(f"Row {i}: {row}")

